<script setup>
import GuestLayout from '@/Layouts/GuestLayout.vue'; import {Head,useForm} from '@inertiajs/vue3'; const form=useForm({password:''}); const submit=()=>form.post(route('password.confirm'),{onFinish:()=>form.reset()});
</script>
<template><Head title="تأكيد كلمة المرور"/><GuestLayout title="تأكيد الهوية" description="هذه منطقة آمنة. أدخل كلمة المرور للمتابعة."><form class="space-y-5" @submit.prevent="submit"><div><label class="mb-1.5 block text-sm font-semibold text-slate-700 dark:text-slate-300">كلمة المرور</label><input v-model="form.password" type="password" autocomplete="current-password" autofocus class="w-full rounded-xl border-slate-300 py-3 focus:border-indigo-500 focus:ring-indigo-500 dark:border-slate-700 dark:bg-slate-950 dark:text-white"/><p v-if="form.errors.password" class="mt-1 text-xs text-rose-600">{{form.errors.password}}</p></div><button :disabled="form.processing" class="w-full rounded-xl bg-indigo-600 px-5 py-3.5 font-bold text-white hover:bg-indigo-700 disabled:opacity-50">تأكيد ومتابعة</button></form></GuestLayout></template>
